         color: var(--muted);
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 600;
       }

       .required-mark {
         color: var(--accent-strong);
       }

       input {
         width: 100%;
         min-width: 0;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         padding: 0.95rem 1rem;
         background: var(--panel-2);
         color: var(--text);
         font: inherit;
         transition: border-color 0.16s ease, box-shadow 0.16s ease, background-color 0.16s ease;
       }

       input::placeholder {
         color: #7281a6;
       }

       input:hover {
         border-color: var(--border-strong);
       }

       input:focus {
         outline: 3px solid transparent;
         border-color: var(--accent-strong);
         box-shadow: 0 0 0 4px #7c9cff33;
       }

       input[aria-invalid="true"] {
         border-color: var(--danger);
         box-shadow: 0 0 0 4px #ff7f9133;
       }

       .hint,
       .error {
         margin: 0;
         font-size: 0.95rem;
       }

       .hint {
         color: var(--muted);
       }

       .error {
         min-height: 1.25rem;
         color: var(--danger);
       }

       .error[hidden] {
         display: block;
         visibility: hidden;
       }

       .actions {
         display: flex;
         justify-content: flex-start;
         padding-top: 0.25rem;
       }

       button {
         appearance: none;
         border: 1px solid #5875c6;
         border-radius: 999px;
         padding: 0.9rem 1.3rem;
         background: linear-gradient(180deg, #7d9dff 0%, #5d7df0 100%);
         color: #081225;
         font: 700 1rem/1 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         cursor: pointer;
         transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease;
       }

       button:hover {
         filter: brightness(1.04);
       }

       button:active {
         transform: translateY(1px);
       }

       button:focus {
         outline: 3px solid transparent;
         box-shadow: 0 0 0 4px #d8e2ff55;
       }

       .status {
         margin: 0 0 1rem;
         min-height: 1.5rem;
         color: var(--accent-strong);
         font-weight: 600;
       }

       @media (max-width: 32rem) {
         .shell {
