         :root {
           --bg: Canvas;
           --panel: Canvas;
           --panel-2: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --border-strong: ButtonBorder;
           --accent: ButtonText;
           --accent-strong: ButtonText;
           --danger: ButtonText;
           --danger-bg: Canvas;
           --focus: Highlight;
         }

         body,
         .card,
         input,
         button,
         .skip-link {
           forced-color-adjust: auto;
         }

         input,
         button,
         .skip-link {
           background: Canvas;
           color: CanvasText;
           border-color: ButtonBorder;
         }

         input:focus,
         button:focus,
         .skip-link:focus {
           outline: 2px solid Highlight;
           box-shadow: none;
         }

         input[aria-invalid="true"] {
           border-color: ButtonText;
           box-shadow: none;
         }
       }
